<?php $items = $items ?? []; ?>
<section class="mx-auto max-w-7xl"><header class="cms-header slide-in"><div><p class="eyebrow">Admin CMS</p><h1 class="section-title mt-3">View Photos</h1><p class="mt-4 max-w-2xl text-base leading-7 text-neutral-600">Galeri foto yang tersimpan di backend.</p></div><a href="/admin/photo-add" class="btn btn-primary">Add New</a></header><section class="admin-card mt-6 p-4 md:p-6" id="admin-photo-list" data-ssr="true"><div class="simple-card-grid"><?php if ($items === []): ?><div class="p-8 text-center text-sm text-neutral-500">Belum ada foto.</div><?php endif; ?><?php foreach ($items as $item): ?><article class="simple-admin-card" data-photo-id="<?= (int) ($item['id'] ?? 0) ?>"><?php if (!empty($item['image'])): ?><img src="<?= $e($item['image']) ?>" alt="<?= $e($item['title'] ?? '') ?>"><?php else: ?><div class="config-empty">No image</div><?php endif; ?><h2 class="mt-4"><?= $e($item['title'] ?? '') ?></h2><?php if (!empty($item['caption'])): ?><p class="mt-2 text-sm text-neutral-600"><?= $e($item['caption']) ?></p><?php endif; ?><div class="mt-4 flex gap-2"><a class="cms-action edit" href="/admin/photo-add?id=<?= (int) ($item['id'] ?? 0) ?>">Edit</a><button class="cms-action delete" type="button" data-photo-delete="<?= (int) ($item['id'] ?? 0) ?>">Delete</button></div></article><?php endforeach; ?></div></section></section>
